// Quantos arquivos baixa ao mesmo tempo.
const PARALLEL = 12;
const FRESH = ['', 'index.html', 'flutter_bootstrap.js', 'main.dart.js', 'version.json'];

self.addEventListener('install', (event) => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    await cache.addAll(CORE.map((f) => new Request(f, {cache: 'reload'})));
    // Resumos da versão guardada: o que não mudou é copiado de lá, sem
    // baixar de novo (antes cada atualização baixava o jogo inteiro).
    let oldCache = null, oldMap = {};
    for (const key of await caches.keys()) {
      if (key === CACHE) continue;
      const c = await caches.open(key);
      const m = await c.match('__manifest');
      if (m) { oldCache = c; oldMap = await m.json(); break; }
    }
    // Avisa a página do progresso (botão "verificar atualizações" mostra a
    // porcentagem). Se algum arquivo falhar, o resto continua.
    const names = Object.keys(FILES);
    let done = 0, lastSent = 0, next = 0;
    const post = async (p) => {
      for (const c of await self.clients.matchAll({includeUncontrolled: true})) {
        c.postMessage({type: 'nova-progress', p});
      }
    };
    const one = async (f) => {
      if (oldCache && oldMap[f] === FILES[f]) {
        const hit = await oldCache.match(f);
        if (hit) { await cache.put(f, hit); return; }
      }
      // 'reload' ignora o cache HTTP: sem isso vinham imagens da versão anterior.
      await cache.add(new Request(f, {cache: 'reload'})).catch(() => null);
    };
    const worker = async () => {
      while (next < names.length) {
        await one(names[next++]);
        done++;
        if (done - lastSent >= 20 || done === names.length) {
          lastSent = done;
          post(done / names.length);
        }
      }
    };
    await Promise.all(Array.from({length: PARALLEL}, worker));
    await cache.put('__manifest', new Response(JSON.stringify(FILES)));
    await self.skipWaiting();
  })());
});

self.addEventListener('activate', (event) => {
  event.waitUntil((async () => {
    for (const key of await caches.keys()) {
      if (key !== CACHE) await caches.delete(key);
    }
    await self.clients.claim();
  })());
});

function withTimeout(promise, ms) {
  return new Promise((resolve, reject) => {
    const t = setTimeout(() => reject(new Error('timeout')), ms);
    promise.then((r) => { clearTimeout(t); resolve(r); }, (e) => { clearTimeout(t); reject(e); });
  });
}

self.addEventListener('fetch', (event) => {
  const req = event.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;
  const path = url.pathname.replace(self.registration.scope.replace(self.location.origin, ''), '');
  const fresh = FRESH.includes(path) || req.mode === 'navigate';

  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    // Arquivos com intervalo (áudio) não entram no cache como parciais.
    const plain = !req.headers.get('range');
    if (fresh) {
      try {
        // 'no-cache': confere no servidor; sem isso o cache HTTP do navegador
        // (10 min no GitHub Pages) devolvia o código e o texto antigos.
        const res = await withTimeout(fetch(req, {cache: 'no-cache'}), 3000);
        if (res.ok && plain) cache.put(req, res.clone());
        return res;
      } catch (e) {
        const hit = await cache.match(req, {ignoreSearch: true})
          || (req.mode === 'navigate' && (await cache.match('index.html') || await cache.match('./')));
        if (hit) return hit;
        throw e;
      }
    }
    const hit = await cache.match(req, {ignoreSearch: true});
    if (hit) return hit;
    const res = await fetch(req);
    if (res.ok && plain && res.status === 200) cache.put(req, res.clone());
    return res;
  })());
});
